import {useState} from 'react';
import {Field,Form,Status} from './ui';
import {Feedback,Section} from './common';
import {platform,useResource,timestamp} from './data';
import ImageUpload from './ImageUpload';
import Orders from './Orders';

export default function Rider(){
 const r=useResource(()=>platform('/rider')),[vehicle,setVehicle]=useState('bicycle');
 const needsPlate=['motorcycle','car','van','truck'].includes(vehicle);
 return <><h1>Your rider workspace</h1><p className="muted">Apply with your vehicle details, complete a manual review, then reserve eligible delivery jobs.</p><Feedback resource={r}/>{r.data?r.data.rider?<><ol className="application-steps" aria-label="Rider application progress"><li className="complete"><span>01</span>Profile submitted</li><li className={r.data.rider.status==='approved'?'complete':''}><span>02</span>{r.data.rider.status==='approved'?'Approved':'Verification review'}</li><li className={r.data.rider.status==='approved'?'complete':''}><span>03</span>{r.data.rider.status==='approved'?'Eligible for jobs':'Jobs locked until approval'}</li></ol><Section title="Your rider profile"><div className="rider-profile"><div><p className="small muted">Rider ID</p><strong className="order-id">{r.data.rider.user_id}</strong><p>{r.data.rider.vehicle}</p>{r.data.rider.vehicle_plate?<p>Plate number · <strong>{r.data.rider.vehicle_plate}</strong></p>:null}<small>Submitted {timestamp(r.data.rider.created_at)}</small>{r.data.rider.plate_photo?<img className="rider-plate-proof" src={r.data.rider.plate_photo} alt="Your submitted vehicle plate photo"/>:null}</div><Status value={r.data.rider.status}/></div></Section>{r.data.rider.status!=='approved'?<p className="notice">Your application is {r.data.rider.status}. Delivery jobs unlock after an administrator reviews your vehicle details and plate photo.</p>:null}<Orders role="rider" compact/></>:<div className="form-panel"><h2>Join the rider network</h2><p className="muted">Your application stays pending until an authorized administrator reviews it. A manager account cannot also register as an ordinary rider.</p><Form submit="Submit rider application" onSubmit={async d=>{await platform('/rider','POST',d);await r.refresh();}}><Field label="Vehicle category"><select name="vehicle" required value={vehicle} onChange={e=>setVehicle(e.target.value)}>{['bicycle','motorcycle','car','van','truck','other'].map(v=><option key={v} value={v}>{v[0].toUpperCase()+v.slice(1)}</option>)}</select></Field>{needsPlate?<><Field label="Vehicle plate number" name="vehiclePlate" required autoComplete="off" maxLength={32} placeholder="Enter the plate number exactly as shown"/><ImageUpload label="Photo of the vehicle plate" name="platePhoto"/><p className="small muted">Use a clear, recent photo that shows the full plate. An administrator reviews it before delivery jobs unlock.</p></>:<p className="small muted">Bicycles and other unregistered vehicles do not need a plate number or plate photo.</p>}</Form></div>:null}</>;
}
